diff --git a/gson/src/main/java/com/google/gson/JsonPrimitive.java b/gson/src/main/java/com/google/gson/JsonPrimitive.java
index 2773373..8333373 100644
--- a/gson/src/main/java/com/google/gson/JsonPrimitive.java
+++ b/gson/src/main/java/com/google/gson/JsonPrimitive.java
@@ -13,6 +13,7 @@
  */
 package com.google.gson;

+import java.math.BigDecimal;
 import java.math.BigInteger;
 import java.util.Objects;

@@ -100,10 +101,10 @@ final class JsonPrimitive extends JsonElement {
     if (this == obj) {
       return true;
     } else if (obj instanceof JsonPrimitive) {
-      JsonPrimitive other = (JsonPrimitive) obj;
-      return value.equals(other.value);
-    } else if (obj instanceof Number) {
-      return value.equals(((Number) obj).doubleValue());
+      JsonPrimitive other = (JsonPrimitive) obj;
+      return value.equals(other.value) || (value instanceof Number && other.value instanceof Number
+          && new BigDecimal(value.toString()).equals(new BigDecimal(other.value.toString())));
+    } else if (obj instanceof Number) {
+      return value.equals(new BigDecimal(obj.toString()));
     } else {
       return false;
     }
